# The start.sh opener and colours, white and silver: the TensorFold ribbon as truecolour terminal art, with MIA AI LAB. The art
# prints on a terminal of 86+ columns; NO_COLOR (even empty), a log or a pipe gets the plain lines alone.
brand_style() {
  AE_INK= AE_QUIET= AE_WHITE= AE_SILVER= AE_RESET=
  if [[ -t 1 && ! ${NO_COLOR+x} && ${TERM:-} != dumb ]]; then
    AE_INK=$'\033[38;2;232;236;240m'
    AE_QUIET=$'\033[38;2;168;174;182m'
    AE_SILVER=$'\033[38;2;200;206;214m'
    AE_WHITE=$'\033[38;2;255;255;255m'
    AE_RESET=$'\033[0m'
  fi
}

